// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address caller1, address caller2, uint256 v1, uint256 v2) public {
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));

        v1 = bound(v1, 0, 1 ether);
        v2 = bound(v2, 0, 1 ether);

        vm.deal(caller1, v1);
        vm.deal(caller2, v2);

        bool ok1;
        bool ok2;

        vm.prank(caller1);
        try c.addToBalance{value: v1}() {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        vm.prank(caller2);
        try c.addToBalance{value: v2}() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(ok1 && ok2);
    }
}
